/* Freezers ESPORT team hub. GitHub credentials live in memory only. */
const DATA_FILES={events:'calendar.json',roster:'roster.json',playbook:'playbook.json',rsvps:'rsvps.json',attendance:'attendance.json',excuses:'excuses.json',admins:'admins.json',staff:'staff.json',logs:'activity.json'};
const DEFAULTS={events:[],roster:{main:[],reserve:[],academy:[]},playbook:{entries:[],maps:[]},rsvps:{},attendance:{},excuses:{},admins:[],staff:[],logs:[]};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getCookie(name){const value=document.cookie.split('; ').find(x=>x.startsWith(encodeURIComponent(name)+'='))?.split('=').slice(1).join('=')||'';try{return decodeURIComponent(value)}catch{return value}}
function setCookie(name,value,days=180){document.cookie=`${encodeURIComponent(name)}=${encodeURIComponent(value)}; Max-Age=${days*86400}; Path=/; SameSite=Lax${location.protocol==='https:'?'; Secure':''}`}
const state={...structuredClone(DEFAULTS),page:'dashboard',adminTab:'events',calendarView:getCookie('freezers_calendar_view')||'month',calendarDate:new Date(),map:'all',search:'',points:120,config:JSON.parse(localStorage.getItem('freezers_config')||localStorage.getItem('gg_config')||JSON.stringify({owner:'feitmenn',repo:'freezers',branch:'main',path:''})),token:'',github:false,authenticated:false,currentUser:null,userRole:null,username:getCookie('freezers_user')||'FILAS'};
const key='freezers_data_v1', overrides=JSON.parse(localStorage.getItem(key)||localStorage.getItem('gg_overrides_v1')||'{}');
function saveLocal(){const o={};for(const k of Object.keys(DATA_FILES))o[k]=state[k];localStorage.setItem(key,JSON.stringify(o))}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3400)}
function log(message,icon='↗'){state.logs.unshift({message,icon,at:new Date().toISOString()});state.logs=state.logs.slice(0,60);saveLocal();renderLogs();if(state.github)githubWrite('logs').catch(e=>toast('Zápis logu na GitHub selhal: '+e.message,'error'))}
function fmtDate(value,opts={weekday:'short',day:'numeric',month:'short'}){return new Intl.DateTimeFormat('cs-CZ',opts).format(new Date(value))}
function monthName(d){return new Intl.DateTimeFormat('cs-CZ',{month:'long',year:'numeric'}).format(d)}
function initials(name){return String(name||'?').trim().slice(0,2).toUpperCase()}
function allPlayers(){return Object.values(state.roster||{}).flat().filter(p=>p&&p.type!=='empty'&&p.name)}
function userByAlias(alias){const a=String(alias).toLowerCase();return allPlayers().find(p=>[p.name,p.faceit?.split('/').pop()].filter(Boolean).some(x=>String(x).toLowerCase()===a))?.name||alias}
function counts(){const players=allPlayers(),absences={};Object.entries(state.attendance||{}).forEach(([event,rows])=>Object.entries(rows||{}).forEach(([user,status])=>{if(status==='unexcused'){const n=userByAlias(user);absences[n]=(absences[n]||0)+1}}));return{players,absences}}
function eventsSorted(){return [...(state.events||[])].sort((a,b)=>new Date(a.date)-new Date(b.date))}
function futureEvents(){return eventsSorted().filter(e=>new Date(e.date)>=new Date(new Date().setHours(0,0,0,0)))}
function typeName(t){return({training:'Trénink',scrim:'Zápas / Scrim',tournament:'Turnaj',meeting:'Meeting'})[t]||t||'Událost'}
function eventType(t){return `<span class="event-type ${esc(t||'')}">${esc(typeName(t))}</span>`}
function eventRow(e){let d=new Date(e.date);return `<div class="event-row" data-event="${esc(e.id)}"><div class="date-block"><b>${d.toLocaleDateString('cs-CZ',{day:'2-digit'})}</b><small>${d.toLocaleDateString('cs-CZ',{month:'short'})}</small></div><div><h4>${esc(e.title)}</h4><p>${d.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})} · ${esc(e.location||'Online / týmový server')}</p></div>${eventType(e.type)}</div>`}
function playerRow(p,absences={},mini=false){const n=absences[p.name]||0,alert=n>=5;return `<div class="player-row ${alert?'alert':''}"><span class="player-avatar">${esc(initials(p.name))}</span><span class="player-info"><b>${esc(p.name)}</b><small>${esc(p.role||typeName(p.type))}${n?` · <span class="${alert?'danger-number':''}">${n}× absence</span>`:''}</small></span>${alert?'<span class="absence-pill">⚠ 5+</span>':`<span class="player-role">${esc(p.type==='captain'?'Kapitán':p.type==='trial'?'Trial':'Aktivní')}</span>`}</div>`}
function pageHeading(kicker,title,sub,action=''){return `<div class="section-head"><div><div class="section-kicker">${kicker}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action?`<div class="section-actions">${action}</div>`:''}</div>`}
function renderDashboard(){const {players,absences}=counts(), ev=futureEvents(),next=ev[0];return `<section class="hero"><div class="hero-content"><span class="hero-tag">OFFICIAL TEAM HUB · SEASON 2026</span><h1>Každý round.<br><span>Jeden tým.</span></h1><p>Vše pro váš další level. Tréninky, sestava i taktiky na jednom místě.</p></div><div class="hero-foot"><img src="assets/logo.png" alt=""> FREEZERS ESPORT</div></section>
${pageHeading('MATCH CENTER','Tým v číslech','Základní přehled týmu Freezers ESPORT.')}
<div class="stats-grid"><div class="stat-card"><span class="stat-icon">♟</span><div class="stat-label">AKTIVNÍ HRÁČI</div><div class="stat-value blue">${players.length.toString().padStart(2,'0')}</div><div class="stat-note">napříč sestavami</div></div><div class="stat-card"><span class="stat-icon">▦</span><div class="stat-label">NADCHÁZEJÍCÍ AKCE</div><div class="stat-value">${ev.length.toString().padStart(2,'0')}</div><div class="stat-note">${next?`další už ${fmtDate(next.date,{day:'numeric',month:'long'})}`:'kalendář je volný'}</div></div><div class="stat-card"><span class="stat-icon">◈</span><div class="stat-label">TAKTIKY V PLAYBOOKU</div><div class="stat-value green">${state.playbook.entries?.length||0}</div><div class="stat-note">${new Set(state.playbook.entries?.map(x=>x.map)).size} aktivní mapy</div></div><div class="stat-card"><span class="stat-icon">⚑</span><div class="stat-label">BODY AKTIVITY</div><div class="stat-value orange">${state.points}</div><div class="stat-note">váš týmový balance</div></div></div>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h3>Nejbližší akce</h3><p>Co vás čeká v následujících dnech.</p></div><a class="text-link" href="#calendar">CELÝ KALENDÁŘ →</a></div><div class="event-list">${ev.length?ev.slice(0,4).map(eventRow).join(''):'<div class="empty"><b>Žádné nadcházející akce</b>Přidejte trénink nebo zápas do kalendáře.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>Main roster</h3><p>Aktuální sestava Freezers ESPORT.</p></div><a class="text-link" href="#roster">SOUPISKA →</a></div><div class="roster-mini">${(state.roster.main||[]).slice(0,5).map(p=>playerRow(p,absences,true)).join('')||'<div class="empty">Sestava je prázdná.</div>'}</div></section></div>
<section class="panel" style="margin-top:14px"><div class="partner-strip"><span class="partner-label">DÍKY NAŠIM PARTNERŮM</span><img src="assets/partner-logos/ceska-asociace-esportu-1789898582762.png" alt="Česká asociace esportu"><img src="assets/partner-logos/fionshop-1789901151541.avif" alt="FionShop"><img src="assets/partner-logos/slovenska-asociacia-elektronickych-sportov-1789901183905.png" alt="Slovenská asociácia elektronických športov"></div></section>`}
function renderCalendar(){if(!state.authenticated)return restrictedPrompt('kalendář');const date=state.calendarDate,events=eventsSorted();const monthStart=new Date(date.getFullYear(),date.getMonth(),1),gridStart=new Date(monthStart);gridStart.setDate(1-((gridStart.getDay()+6)%7));const today=new Date();let days=42;if(state.calendarView==='week')days=7;if(state.calendarView==='day')days=1;let start=new Date(gridStart);if(state.calendarView==='week'){start=new Date(date);start.setDate(date.getDate()-((date.getDay()+6)%7))}if(state.calendarView==='day')start=new Date(date);const cells=Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const iso=d.toISOString().slice(0,10),dayEvents=events.filter(e=>new Date(e.date).toISOString().slice(0,10)===iso);return `<div class="day-cell ${d.getMonth()===date.getMonth()?'':'muted-day'}" data-day="${iso}"><div class="day-number ${d.toDateString()===today.toDateString()?'today':''}"><span>${d.getDate()}</span>${dayEvents.length?`<span>${dayEvents.length} akc.</span>`:''}</div>${dayEvents.slice(0,3).map(e=>`<div class="cal-event ${esc(e.type||'')}" data-event="${esc(e.id)}">${d.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})} ${esc(e.title)}</div>`).join('')}</div>`}).join('');const next=events.filter(e=>new Date(e.date)>=new Date(new Date().setHours(0,0,0,0))).slice(0,9);return `${pageHeading('PLÁNOVÁNÍ TÝMU','Kalendář','Tréninky, zápasy a turnaje na jednom místě.',`<button class="btn btn-primary" data-action="add-event">＋ Přidat událost</button>`)}<div class="section-head" style="margin-top:0;align-items:center"><div class="calendar-toolbar"><button class="btn btn-small" data-action="cal-prev">←</button><h2 class="month-title">${esc(monthName(date))}</h2><button class="btn btn-small" data-action="cal-next">→</button><button class="btn btn-small btn-ghost" data-action="cal-today">Dnes</button></div><div class="view-switch">${['month','week','day'].map(v=>`<button data-view="${v}" class="${state.calendarView===v?'active':''}">${({month:'Měsíc',week:'Týden',day:'Den'})[v]}</button>`).join('')}</div></div><div class="calendar-layout"><div class="calendar-box"><div class="calendar-head">${['PO','ÚT','ST','ČT','PÁ','SO','NE'].map(x=>`<div>${state.calendarView==='day'?'ČAS':x}</div>`).join('')}</div><div class="calendar-grid">${cells}</div></div><aside class="calendar-side"><section class="panel"><div class="panel-head"><div><h3>Nejbližší akce</h3><p>${next.length} naplánovaných</p></div></div><div class="date-list">${next.length?next.map(eventRow).join(''):'<div class="empty">Nic v plánu.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Typy akcí</h3></div><div class="record-line"><span>Trénink</span>${eventType('training')}</div><div class="record-line"><span>Scrim / zápas</span>${eventType('scrim')}</div><div class="record-line"><span>Turnaj</span>${eventType('tournament')}</div></section></aside></div>`}
function renderPlaybook(){if(!state.authenticated)return restrictedPrompt('playbook');const maps=state.playbook.maps||[], entries=state.playbook.entries||[], shown=entries.filter(e=>(state.map==='all'||e.map===state.map)&&(!state.search||`${e.title} ${e.map} ${e.description}`.toLowerCase().includes(state.search.toLowerCase())));return `${pageHeading('TAKTICKÁ PŘÍPRAVA','Playbook','Callouty a setupy připravené na další mapu.',`<button class="btn btn-primary" data-action="add-strat">＋ Přidat taktiku</button>`)}<div class="field" style="max-width:320px;margin-bottom:12px"><input id="stratSearch" type="search" value="${esc(state.search)}" placeholder="⌕  Hledat taktiku, mapu nebo callout…"></div><div class="map-grid"><div class="map-card ${state.map==='all'?'active':''}" data-map="all"><img src="assets/mountain.png" alt="Všechny mapy"><b>Všechny mapy</b><small>${entries.length} TAKTIK</small></div>${maps.map(m=>`<div class="map-card ${state.map===m.name?'active':''}" data-map="${esc(m.name)}"><img src="${esc(mapImage(m))}" alt="${esc(m.name)}"><b>${esc(m.name)}</b><small>${entries.filter(e=>e.map===m.name).length} TAKTIK</small></div>`).join('')}</div><div class="playbook-grid">${shown.map(e=>`<article class="strat-card"><div class="strat-top"><h3>${esc(e.title)}</h3>${eventType('scrim')}</div><p>${esc(e.description||'Video ukázka týmové taktiky.')}</p><div class="strat-foot"><span>${esc(e.map)} · ${e.addedAt?fmtDate(e.addedAt,{day:'numeric',month:'short',year:'numeric'}):'týmový setup'}</span>${e.videoLink?`<a href="${esc(e.videoLink)}" target="_blank" rel="noopener">▶ Zobrazit video</a>`:''}</div></article>`).join('')||'<div class="empty panel" style="grid-column:1/-1">Žádné taktiky tomuto filtru neodpovídají.</div>'}</div>`}
function mapImage(m){const file=(m.image||'').split('/').pop();return `assets/playbook-maps/${encodeURIComponent(file)}`}
function renderRosterGroup(group,items,absences){const labels={main:['MAIN ROSTER','HLAVNÍ SESTAVA'],reserve:['RESERVE MAIN','REZERVA'],academy:['ACADEMY','AKADEMIE'],'academy-reserve':['ACADEMY · RESERVE','REZERVA AKADEMIE']},[kicker,title]=labels[group]||[group.toUpperCase(),group];return `<section class="panel"><div class="panel-head"><div><span class="section-kicker">${kicker}</span><h3 class="group-head">${title}<span>${items.filter(p=>p?.name&&p.type!=='empty').length} HRÁČŮ</span></h3></div></div><div class="players-grid">${items.map(p=>{if(!p||p.type==='empty')return `<a class="vacancy-card" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener"><span class="vacancy-plus">＋</span><span><b>Volné místo</b><small>Přidej se k týmu na Discordu ↗</small></span></a>`;const n=absences[p.name]||0;return `<div class="player-card ${n>=5?'alert':''}"><span class="player-avatar">${esc(initials(p.name))}</span><span class="player-info"><b>${esc(p.name)}</b><small>${esc(p.role||'Člen týmu')}</small></span>${p.faceit?`<a class="text-link" href="${esc(p.faceit)}" target="_blank" rel="noopener">FACEIT ↗</a>`:''}${n>=5?`<span class="absence-pill">⚠ ${n}×</span>`:''}</div>`}).join('')||'<div class="empty">Zatím zde nejsou žádní hráči.</div>'}</div></section>`}
function renderRoster(){const {absences}=counts();return `${pageHeading('SESTAVY FREEZERS','Roster','Čtyři úrovně, jeden tým. Volná místa jsou otevřená — klikni a přidej se do komunity.') }<div class="roster-groups">${Object.entries(state.roster||{}).map(([group,players])=>renderRosterGroup(group,players||[],absences)).join('')}</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><span class="section-kicker">PŘIDEJ SE K FREEZERS</span><h3 class="group-head">Hledáme nové tváře</h3><p>Napiš nám na Discordu a představ se týmu.</p></div><a class="btn btn-primary" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener">Připojit se na Discord ↗</a></div></section>`}function renderHazard(){const upcoming=futureEvents();return `${pageHeading('TEAM PREDICTIONS','Tipovačka','Přátelské predikce a týmové body. Bez skutečných peněz.') }<div class="hazard-hero"><div><span class="eyebrow">TVŮJ TEAM BALANCE</span><div class="points">${state.points}<small>GLOCK COINS · INTERNÍ BODY</small></div></div><span style="font-size:42px">♧</span></div><div class="section-head"><div><div class="section-kicker">DALŠÍ MATCHDAY</div><h2>Na co si tipneš?</h2></div></div><div class="content-grid">${upcoming.filter(e=>e.type==='scrim'||e.type==='tournament').slice(0,4).map(e=>{const picked=JSON.parse(localStorage.getItem('gg_picks')||'{}')[e.id];return `<section class="panel"><div class="panel-head"><div><h3>${esc(e.title)}</h3><p>${fmtDate(e.date,{weekday:'long',day:'numeric',month:'long'})} · ${new Date(e.date).toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})}</p></div>${eventType(e.type)}</div><div class="pick-row"><button class="pick-button ${picked==='win'?'selected':''}" data-pick="win" data-match="${esc(e.id)}"><b>⚡ Výhra</b>+ 15 bodů</button><button class="pick-button ${picked==='lose'?'selected':''}" data-pick="lose" data-match="${esc(e.id)}"><b>◉ Těsný zápas</b>+ 5 bodů</button></div><p style="padding:0 13px 12px;color:#69788c;font-size:8px">Vyhodnocení mohou provést administrátoři po zápase.</p></section>`}).join('')||'<div class="empty panel" style="grid-column:1/-1"><b>Zatím nejsou naplánované zápasy</b>Až se v kalendáři objeví scrim nebo turnaj, budete si moct tipnout.</div>'}</div><div class="notice warn" style="margin-top:14px">🎮 Body jsou čistě zábavný prvek pro týmovou motivaci. Nejde o peníze ani skutečné sázení.</div>`}
function renderAdmin(){const events=eventsSorted(),tab=state.adminTab;return `${pageHeading('KONTROLA TÝMU','Administrace','Správa kalendáře, docházky a synchronizace.') }<div class="admin-tabs">${[['events','Kalendář'],['attendance','Docházka'],['sync','GitHub Sync'],['users','Účty / admini'],['storage','Data & zálohy']].map(([v,label])=>`<button class="tab-button ${tab===v?'active':''}" data-admin-tab="${v}">${label}</button>`).join('')}</div>${tab==='events'?`<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Nová událost</h3><p>Vytvořte trénink, zápas nebo turnaj.</p></div></div><div style="padding:15px"><form id="eventForm"><div class="form-grid"><div class="field full"><label>NÁZEV AKCE</label><input required name="title" maxlength="90" placeholder="Např. Main roster · Inferno training"></div><div class="field"><label>DATUM A ČAS</label><input required type="datetime-local" name="date"></div><div class="field"><label>TYP AKCE</label><select name="type"><option value="training">Trénink</option><option value="scrim">Scrim / zápas</option><option value="tournament">Turnaj</option><option value="meeting">Meeting</option></select></div><div class="field"><label>POVINNÁ ÚČAST</label><select name="mandatory"><option value="yes">Ano, povinná</option><option value="no">Ne, dobrovolná</option></select></div><div class="field"><label>MAPA / MÍSTO</label><input name="location" maxlength="60" placeholder="Inferno · FACEIT"></div><div class="field full"><label>POZNÁMKY PRO TÝM</label><textarea name="description" maxlength="700" placeholder="Plán, příprava a další informace…"></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">＋ Vytvořit událost</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h3>V kalendáři</h3><p>${events.length} akcí celkem</p></div></div><div class="date-list">${events.slice().reverse().slice(0,8).map(e=>`${eventRow(e)}<div style="text-align:right;margin-top:-7px;margin-bottom:7px"><button class="btn btn-small btn-danger" data-delete-event="${esc(e.id)}">Odstranit</button></div>`).join('')||'<div class="empty">Kalendář je prázdný.</div>'}</div></section></div>`:tab==='attendance'?`<section class="panel"><div class="panel-head"><div><h3>Správa docházky</h3><p>Označte stav člena po uskutečněné události.</p></div></div><div style="padding:15px"><div class="field" style="max-width:460px"><label>VYBRAT UDÁLOST</label><select id="attendanceEvent">${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)} · ${fmtDate(e.date,{day:'numeric',month:'short'})}</option>`).join('')}</select></div><div id="attendanceRows" style="margin-top:12px"></div></div></section>`:tab==='users'?renderAccountTab():tab==='sync'?renderSyncTab():renderStorageTab()}`}
function renderSyncTab(){const c=state.config;const connected=!!state.github;return `<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>GitHub Contents API</h3><p>Synchronizace JSON souborů přímo do vašeho repozitáře.</p></div></div><div style="padding:15px"><div class="notice warn"><b>Bezpečnost tokenu:</b> statický web neumí před návštěvníky ukrýt GitHub token. Token se uchovává pouze v paměti této karty, nikdy se nezapisuje do repozitáře ani localStorage. Použijte jemně omezený token s přístupem jen k tomuto repozitáři.</div><form id="syncForm" style="margin-top:14px"><div class="form-grid"><div class="field"><label>VLASTNÍK REPOZITÁŘE</label><input name="owner" required value="${esc(c.owner||'')}" placeholder="např. feitmenn"></div><div class="field"><label>NÁZEV REPOZITÁŘE</label><input name="repo" required value="${esc(c.repo||'')}" placeholder="např. freezers"></div><div class="field"><label>BRANCH</label><input name="branch" value="${esc(c.branch||'main')}" placeholder="main"></div><div class="field"><label>CESTA K JSON SOUBORŮM</label><input name="path" value="${esc(c.path||'')}" placeholder="prázdné = kořen repozitáře"></div><div class="field full"><label>GITHUB TOKEN (fine-grained, contents read/write)</label><input type="password" name="token" autocomplete="off" placeholder="ghp_… / github_pat_…" value=""></div></div><div class="form-actions"><button class="btn" type="button" data-action="disconnect">Odpojit</button><button class="btn btn-primary" type="submit">Připojit a načíst data</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h3>Stav synchronizace</h3><p>Kontrola připojení k týmovým datům.</p></div></div><div class="github-status"><div class="status-indicator ${connected?'connected':''}"><span class="sync-light"></span>${connected?'PŘIPOJENO K GITHUBU':'ČEKÁ NA NASTAVENÍ'}</div><p>${connected?`<b>${esc(c.owner)}/${esc(c.repo)}</b><br>Větev: ${esc(c.branch||'main')}`:'Zadejte repozitář a token pro aktivaci.'}</p><button class="btn btn-small" data-action="sync-now" ${connected?'':'disabled'}>↻ Načíst aktuální data</button></div><div class="record-line"><span>calendar.json</span><span>${state.events.length} záznamů</span></div><div class="record-line"><span>roster.json</span><span>${allPlayers().length} hráčů</span></div><div class="record-line"><span>playbook.json</span><span>${state.playbook.entries?.length||0} taktik</span></div><div class="record-line"><span>attendance.json</span><span>${Object.keys(state.attendance).length} akcí</span></div></section></div>`}
function render(){if(state.authenticated)$('#loginScreen').hidden=true;const route=location.hash.slice(1)||state.page;state.page=['dashboard','calendar','playbook','roster','hazard','member','admin'].includes(route)?route:'dashboard';if(state.page==='admin'&&!isAdmin()){state.page='dashboard';location.hash='dashboard'}if(state.adminTab==='storage'&&state.userRole!=='owner')state.adminTab='events';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page==='admin')a.hidden=!isAdmin()});$('#breadcrumb').textContent=({dashboard:'PŘEHLED',calendar:'KALENDÁŘ',playbook:'PLAYBOOK',roster:'SOUPISKA',hazard:'TIPOVAČKA',member:'ČLENSKÁ SEKCE',admin:'ADMINISTRACE'})[state.page];$('#sideUsername').textContent=state.authenticated?state.username:'Přihlásit se';$('#topUsername').textContent=state.authenticated?state.username:'Přihlásit se';$('#sideRole').textContent=state.authenticated?String(state.userRole||'member').toUpperCase():'Členský přístup';$('#page').innerHTML=({dashboard:renderDashboard,calendar:renderCalendar,playbook:renderPlaybook,roster:renderRoster,hazard:renderHazard,member:renderMember,admin:renderAdmin})[state.page]();$('#upcomingCount').textContent=futureEvents().length||'';renderLogs();$('#syncLabel').textContent=state.github?'GitHub propojen':'Lokální režim';$('#syncHint').textContent=state.github?`${state.config.owner}/${state.config.repo}`:'Změny zůstávají v tomto prohlížeči';$('#syncLight').style.background=state.github?'var(--green)':'var(--orange)';if(state.adminTab==='attendance'&&state.page==='admin')renderAttendanceEditor()}
function renderLogs(){if(!$('#activityList'))return;$('#activityList').innerHTML=state.logs.length?state.logs.slice(0,35).map(a=>`<div class="activity-item"><span class="activity-icon">${esc(a.icon||'↗')}</span><div><p>${esc(a.message)}</p><time>${a.at?fmtDate(a.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'právě teď'}</time></div></div>`).join(''):'<div class="empty">Zatím žádná aktivita.<br>Události se zde objeví po první změně.</div>'}
function renderAttendanceEditor(){const sel=$('#attendanceEvent');if(!sel)return;const id=sel.value||state.events[0]?.id;if(!id){$('#attendanceRows').innerHTML='<div class="empty">Nejprve vytvořte událost.</div>';return}$('#attendanceRows').innerHTML=allPlayers().map(p=>{const status=state.attendance[id]?.[p.name]||'unmarked';return `<div class="record-line"><span>${esc(p.name)}</span><select data-attendee="${esc(p.name)}" style="background:#0a1019;color:#ccd6e4;border:1px solid #293547;border-radius:4px;padding:5px;font-size:9px"><option value="unmarked" ${status==='unmarked'?'selected':''}>Neoznačeno</option><option value="present" ${status==='present'?'selected':''}>Přítomen</option><option value="excused" ${status==='excused'?'selected':''}>Omluven</option><option value="unexcused" ${status==='unexcused'?'selected':''}>Neomluven</option></select></div>`}).join('')}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function eventModal(id){const e=state.events.find(x=>x.id===id);if(!e)return;const rsvps=state.rsvps[id]||{},me=state.username.toLowerCase(),my=Object.entries(rsvps).find(([u])=>u.toLowerCase()===me)?.[1];modal(`<span class="eyebrow">TÝMOVÝ KALENDÁŘ</span><h2>${esc(e.title)}</h2><div class="detail-meta">${eventType(e.type)}<span>▦ ${fmtDate(e.date,{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}</span><span>${e.mandatory==='yes'?'● Povinná účast':'○ Dobrovolná účast'}</span></div>${e.location?`<p class="detail-description">⌖ ${esc(e.location)}</p>`:''}<p class="detail-description">${esc(e.description||'Bez dalších poznámek.')}</p><div class="notice" style="margin-top:15px">${Object.keys(rsvps).length} hráčů odpovědělo · ${Object.values(rsvps).filter(x=>x==='yes').length} dorazí</div><div class="form-actions"><button class="btn ${my==='yes'?'btn-primary':''}" data-rsvp="yes" data-event="${esc(id)}">✓ Dorazím</button><button class="btn ${my==='no'?'btn-primary':''}" data-rsvp="no" data-event="${esc(id)}">✕ Nedostavím se</button><button class="btn" data-action="excuse" data-event="${esc(id)}">Poslat omluvenku</button></div>`)}
function addEventModal(){modal(`<span class="eyebrow">NOVÝ TÝMOVÝ BLOK</span><h2>Přidat událost</h2><form id="quickEventForm"><div class="form-grid"><div class="field full"><label>NÁZEV</label><input name="title" required maxlength="90" placeholder="Main roster · Trénink"></div><div class="field"><label>DATUM A ČAS</label><input name="date" required type="datetime-local" value="${new Date(Date.now()+86400000).toISOString().slice(0,16)}"></div><div class="field"><label>TYP</label><select name="type"><option value="training">Trénink</option><option value="scrim">Scrim / zápas</option><option value="tournament">Turnaj</option><option value="meeting">Meeting</option></select></div><div class="field"><label>ÚČAST</label><select name="mandatory"><option value="yes">Povinná</option><option value="no">Dobrovolná</option></select></div><div class="field"><label>MAPA / MÍSTO</label><input name="location" maxlength="60"></div><div class="field full"><label>POPIS</label><textarea name="description" maxlength="700"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Vytvořit</button></div></form>`)}
function createEvent(form){const fd=new FormData(form),date=new Date(fd.get('date'));if(!fd.get('title').trim()||isNaN(date)){toast('Zkontrolujte název a datum události.','error');return}const e={id:'ev_'+Date.now(),title:fd.get('title').trim(),date:date.toISOString(),type:fd.get('type'),description:fd.get('description').trim(),location:fd.get('location').trim(),mandatory:fd.get('mandatory'),createdBy:state.username};state.events.push(e);saveLocal();log(`${state.username} přidal událost „${e.title}“.`,'▦');persist('events');$('#modal').close();render();toast('Událost byla přidána do kalendáře.')}
function excuse(id){const reason=prompt('Důvod omluvenky (volitelné):','');if(reason===null)return;state.rsvps[id]??={};state.rsvps[id][state.username]='excused';state.attendance[id]??={};state.attendance[id][state.username]='excused';state.excuses[id]??={};state.excuses[id][state.username]={reason:reason.trim(),submittedAt:new Date().toISOString()};saveLocal();log(`${state.username} poslal omluvenku k události „${state.events.find(e=>e.id===id)?.title||id}“.`,'✎');persist('rsvps');persist('attendance');persist('excuses');$('#modal').close();render();toast('Omluvenka byla zaznamenána.')}
function rsvp(id,value){state.rsvps[id]??={};state.rsvps[id][state.username]=value;saveLocal();log(`${state.username} ${value==='yes'?'potvrdil účast':'odmítl účast'} na „${state.events.find(e=>e.id===id)?.title||id}“.`,'✓');persist('rsvps');$('#modal').close();render();toast(value==='yes'?'Účast potvrzena.':'Odpověď uložena.')}
function pick(id,value){const p=JSON.parse(localStorage.getItem('gg_picks')||'{}');if(p[id]){toast('Tip na tuto událost už máte uložený.','error');return}p[id]=value;localStorage.setItem('gg_picks',JSON.stringify(p));toast(value==='win'?'Tip na výhru zaznamenán!':'Tip na těsný zápas zaznamenán!');render()}
function setAttendance(id,user,status){state.attendance[id]??={};if(status==='unmarked')delete state.attendance[id][user];else state.attendance[id][user]=status;saveLocal();persist('attendance');log(`${state.username} změnil docházku hráče ${user}.`,'♟');render()}
function persist(kind){saveLocal();if(state.github)githubWrite(kind).then(()=>toast(`${DATA_FILES[kind]} synchronizován.`)).catch(e=>toast(`GitHub: ${e.message}`,'error'))}
async function githubRequest(path,options={}){const {owner,repo,branch='main',path:base=''}=state.config,filepath=[base,path].filter(Boolean).join('/');const url=`https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/contents/${filepath.split('/').map(encodeURIComponent).join('/')}?ref=${encodeURIComponent(branch)}`;const res=await fetch(url,{...options,headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${state.token}`, 'X-GitHub-Api-Version':'2022-11-28',...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});if(!res.ok){const msg=await res.text();throw Error(`${res.status}: ${msg.slice(0,180)}`)}return res.json()}
async function githubRead(kind){try{const file=await githubRequest(DATA_FILES[kind]);return JSON.parse(decodeURIComponent(escape(atob(file.content.replace(/\n/g,'')))))}catch(e){if(String(e.message).startsWith('404:'))return structuredClone(DEFAULTS[kind]);throw e}}
async function githubWrite(kind){if(!state.github||!state.token)return;const filepath=[state.config.path,DATA_FILES[kind]].filter(Boolean).join('/'),url=`https://api.github.com/repos/${encodeURIComponent(state.config.owner)}/${encodeURIComponent(state.config.repo)}/contents/${filepath.split('/').map(encodeURIComponent).join('/')}`;const get=await fetch(`${url}?ref=${encodeURIComponent(state.config.branch||'main')}`,{headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${state.token}`,'X-GitHub-Api-Version':'2022-11-28'}});let sha;if(get.ok)sha=(await get.json()).sha;else if(get.status!==404)throw Error(`${get.status}: ${await get.text()}`);const content=btoa(unescape(encodeURIComponent(JSON.stringify(state[kind],null,2)+'\n')));const res=await fetch(url,{method:'PUT',headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${state.token}`,'X-GitHub-Api-Version':'2022-11-28','Content-Type':'application/json'},body:JSON.stringify({message:`Update ${DATA_FILES[kind]} from Freezers ESPORT Team Hub`,content,...(sha?{sha}:{}),branch:state.config.branch||'main'})});if(!res.ok)throw Error(`${res.status}: ${(await res.text()).slice(0,180)}`);return res.json()}
async function syncAll(){toast('Načítám týmová data z GitHubu…');const keys=Object.keys(DATA_FILES).filter(k=>k!=='admins');const result=await Promise.all(keys.map(k=>githubRead(k)));keys.forEach((k,i)=>state[k]=result[i]);state.github=true;saveLocal();log('Synchronizace s GitHub repozitářem proběhla úspěšně.','↻');render();toast('Týmová data jsou aktuální.')}
document.addEventListener('click',e=>{if(e.target.closest('.modal-close')){$('#modal').close();return}const removeAccount=e.target.closest('[data-remove-account]');if(removeAccount){if(state.userRole!=='owner'){toast('Účty může odebírat jen owner.','error');return}const name=removeAccount.dataset.removeAccount;if(confirm('Odebrat účet '+name+'?')){state.admins=state.admins.filter(a=>a.username.toLowerCase()!==name.toLowerCase());saveLocal();log('Owner odebral účet '+name+'.','×');persist('admins');render()}return}const del=e.target.closest('[data-delete-event]');if(del&&confirm('Opravdu odstranit tuto událost?')){const id=del.dataset.deleteEvent;state.events=state.events.filter(x=>x.id!==id);saveLocal();log('Admin odstranil událost.','×');persist('events');render();toast('Událost odstraněna.');return}const a=e.target.closest('a[data-page]');if(a){$('#sidebar').classList.remove('open');return}const ev=e.target.closest('[data-event]');if(ev&&!ev.closest('[data-action]')&&!e.target.closest('[data-rsvp]')){eventModal(ev.dataset.event);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='open-login'){openLogin();return}if(action==='logout'){logout();return}if(action==='add-event'){ if(!isAdmin()){toast('Tuto akci může upravit jen admin.','error');return}addEventModal()}if(action==='cal-prev'){state.calendarDate.setMonth(state.calendarDate.getMonth()-1);render()}if(action==='cal-next'){state.calendarDate.setMonth(state.calendarDate.getMonth()+1);render()}if(action==='cal-today'){state.calendarDate=new Date();render()}if(action==='disconnect'){state.github=false;state.token='';toast('GitHub token byl odstraněn z paměti.');render()}if(action==='sync-now')syncAll().catch(err=>toast(err.message,'error'));if(action==='export-data')exportBackup();if(action==='edit-name'){const name=prompt('Jaké jméno se má zobrazovat?',state.username);if(name?.trim()){state.username=name.trim().slice(0,32);setCookie('freezers_user',state.username);render();toast('Zobrazované jméno bylo uloženo do cookie.')}}if(action==='reset-local'&&confirm('Odstranit místní změny a znovu načíst původní JSON soubory?')){localStorage.removeItem(key);localStorage.removeItem('gg_overrides_v1');location.reload()}if(action==='excuse')excuse(e.target.closest('[data-event]').dataset.event);if(action==='add-strat'&&isAdmin())modal(`<span class="eyebrow">CS2 TACTICAL BOARD</span><h2>Přidat taktiku</h2><form id="stratForm"><div class="form-grid"><div class="field full"><label>NÁZEV SETUPU</label><input required name="title" maxlength="90"></div><div class="field"><label>MAPA</label><select name="map">${(state.playbook.maps||[]).map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>VIDEO LINK</label><input name="videoLink" type="url" placeholder="https://youtu.be/…"></div><div class="field full"><label>POKYN / NADHOZY</label><textarea name="description"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Uložit taktiku</button></div></form>`);const map=e.target.closest('[data-map]');if(map){state.map=map.dataset.map;render()}const view=e.target.closest('[data-view]');if(view){state.calendarView=view.dataset.view;setCookie('freezers_calendar_view',state.calendarView);render()}const tab=e.target.closest('[data-admin-tab]');if(tab){state.adminTab=tab.dataset.adminTab;render()}const pickBtn=e.target.closest('[data-pick]');if(pickBtn)pick(pickBtn.dataset.match,pickBtn.dataset.pick);const rsvpBtn=e.target.closest('[data-rsvp]');if(rsvpBtn)rsvp(rsvpBtn.dataset.event,rsvpBtn.dataset.rsvp);if(e.target.id==='logToggle')$('#activityPanel').classList.toggle('open');if(e.target.id==='closeLogs')$('#activityPanel').classList.remove('open');if(e.target.id==='mobileMenu')$('#sidebar').classList.toggle('open');if(e.target.closest('#profileButton,#topProfile')){if(state.authenticated)logout();else openLogin()}});
document.addEventListener('submit',e=>{if(e.target.id==='loginForm'){e.preventDefault();login(e.target)}if(e.target.id==='accountForm'){e.preventDefault();createAccount(e.target)}if(e.target.id==='changePasswordForm'){e.preventDefault();changePassword(e.target)}if(e.target.id==='eventForm'||e.target.id==='quickEventForm'){e.preventDefault();createEvent(e.target)}if(e.target.id==='stratForm'){e.preventDefault();const f=new FormData(e.target);state.playbook.entries.push({title:f.get('title').trim(),map:f.get('map'),videoLink:f.get('videoLink'),description:f.get('description'),addedAt:new Date().toISOString()});saveLocal();log(`${state.username} přidal taktiku „${f.get('title')}“.`,'◈');persist('playbook');$('#modal').close();render();toast('Taktika uložena do playbooku.')}if(e.target.id==='syncForm'){e.preventDefault();const f=new FormData(e.target);state.config={owner:f.get('owner').trim(),repo:f.get('repo').trim(),branch:f.get('branch').trim()||'main',path:f.get('path').trim().replace(/^\/+|\/+$/g,'')};state.token=f.get('token').trim()||state.token;localStorage.setItem('freezers_config',JSON.stringify(state.config));if(!state.token){toast('Zadejte GitHub token.','error');return}syncAll().catch(err=>{state.github=false;toast(`Připojení selhalo: ${err.message}`,'error');render()})}});
document.addEventListener('change',e=>{if(e.target.id==='importFile'&&e.target.files?.[0]){if(state.userRole!=='owner'){toast('Zálohu může obnovit jen owner.','error');return}importBackup(e.target.files[0])}if(e.target.id==='attendanceEvent')renderAttendanceEditor();if(e.target.matches('[data-attendee]'))setAttendance($('#attendanceEvent').value,e.target.dataset.attendee,e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='stratSearch'){state.search=e.target.value;const pos=e.target.selectionStart;render();const input=$('#stratSearch');input.focus();input.setSelectionRange(pos,pos)}});
window.addEventListener('hashchange',render);
async function init(){if(!['month','week','day'].includes(state.calendarView))state.calendarView='month';if(!getCookie('freezers_user'))setCookie('freezers_user',state.username);for(const k of Object.keys(DATA_FILES)){if(Object.hasOwn(overrides,k)&&(k!=='admins'||overrides.admins?.every(a=>a.salt&&a.passwordHash&&a.iterations)))state[k]=overrides[k]}try{const keys=Object.keys(DATA_FILES).filter(k=>!Object.hasOwn(overrides,k)||(k==='admins'&&!overrides.admins?.every(a=>a.salt&&a.passwordHash&&a.iterations)));const vals=await Promise.all(keys.map(async k=>{try{const r=await fetch(DATA_FILES[k]);if(!r.ok)throw Error('missing');return await r.json()}catch{return structuredClone(DEFAULTS[k])}}));keys.forEach((k,i)=>state[k]=vals[i])}catch{}state.logs=state.logs||[];render();if(state.config.owner&&state.config.repo)toast('Lokální týmová data načtena. Pro GitHub Sync zadejte token v Administraci.')}
function storageBytes(){return new Blob([localStorage.getItem(key)||'{}']).size}
function renderStorageTab(){const bytes=storageBytes(),cookieView=getCookie('freezers_calendar_view'),cookieUser=getCookie('freezers_user');return `<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Lokální data</h3><p>Změny se průběžně ukládají do tohoto prohlížeče.</p></div></div><div class="github-status"><div class="status-indicator connected"><span class="sync-light"></span>ULOŽENO V TOMTO PROHLÍŽEČI</div><p>JSON data používají Local Storage. Obsazeno přibližně <b>${(bytes/1024).toFixed(1)} KB</b>. Záloha je přenositelný JSON soubor, který můžete uložit na disk.</p><div class="section-actions"><button class="btn btn-primary" data-action="export-data">↓ Stáhnout zálohu JSON</button><button class="btn btn-danger" data-action="reset-local">Obnovit původní data</button></div></div></section><section class="panel"><div class="panel-head"><div><h3>Obnovit ze souboru</h3><p>Načtení zálohy Freezers ESPORT ve formátu JSON.</p></div></div><div style="padding:15px"><div class="field"><label>VYBRAT ZÁLOŽNÍ SOUBOR</label><input type="file" id="importFile" accept=".json,application/json"></div><p style="font-size:9px;color:#7e8da2;line-height:1.6">Importovaná data nahradí místní kopii. Před importem si stáhněte aktuální zálohu.</p></div></section><section class="panel"><div class="panel-head"><div><h3>Cookies pro nastavení</h3><p>Jen krátké preference, nikdy hesla ani GitHub token.</p></div></div><div class="record-line"><span>Pohled kalendáře</span><span>${esc(cookieView||'zatím nenastaveno')}</span></div><div class="record-line"><span>Zobrazované jméno</span><span>${esc(cookieUser||'FILAS')}</span></div><div class="github-status"><p>Cookies si pamatují drobná nastavení. Kalendář, soupisky a další týmová data zůstávají v Local Storage nebo v JSON souborech.</p><button class="btn btn-small" data-action="edit-name">Změnit zobrazované jméno</button></div></section><section class="panel"><div class="panel-head"><div><h3>Co je v záloze</h3><p>Všechny soubory aplikace pohromadě.</p></div></div>${Object.keys(DATA_FILES).map(k=>`<div class="record-line"><span>${esc(DATA_FILES[k])}</span><span>${Array.isArray(state[k])?state[k].length+' záznamů':Object.keys(state[k]||{}).length+' položek'}</span></div>`).join('')}</section></div>`}
function renderAccountTab(){const owner=state.userRole==='owner';return `${pageHeading('PŘÍSTUPY','Účty a administrátoři','Účet FILAS má roli owner. Owner může zakládat další účty a udělovat roli admina.') }<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Týmové účty</h3><p>${state.admins.length} přihlašovacích účtů</p></div></div>${state.admins.map(a=>`<div class="record-line"><span>${esc(a.username)} ${a.username.toLowerCase()==='filas'?'<small style="color:#ffc46b">· OWNER</small>':''}</span><span><span class="event-type">${esc(String(a.role||'member').toUpperCase())}</span>${owner&&a.role!=='owner'?` <button class="btn btn-small btn-danger" data-remove-account="${esc(a.username)}">Odebrat</button>`:''}</span></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h3>Přidat účet</h3><p>Heslo se uloží jako odvozený hash, ne jako text.</p></div></div>${owner?`<div style="padding:15px"><form id="accountForm"><div class="form-grid"><div class="field full"><label>USERNAME</label><input name="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_.-]+" autocomplete="off"></div><div class="field full"><label>HESLO (MIN. 10 ZNAKŮ)</label><input name="password" type="password" required minlength="10" autocomplete="new-password"></div><div class="field full"><label>ROLE</label><select name="role"><option value="member">Člen</option><option value="admin">Admin</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Vytvořit účet</button></div></form></div>`:'<div class="empty">Nové účty a další adminy může přidávat jen owner FILAS.</div>'}</section></div><section class="panel" style="margin-top:13px"><div class="panel-head"><div><h3>Změnit své heslo</h3><p>Po prvním přihlášení nahraď výchozí heslo silným heslem.</p></div></div><div style="padding:15px"><form id="changePasswordForm"><div class="form-grid"><div class="field"><label>SOUČASNÉ HESLO</label><input type="password" name="currentPassword" required autocomplete="current-password"></div><div class="field"><label>NOVÉ HESLO (MIN. 10 ZNAKŮ)</label><input type="password" name="newPassword" required minlength="10" autocomplete="new-password"></div></div><div class="form-actions"><button class="btn btn-primary">Uložit nové heslo</button></div></form></div></section><div class="notice warn" style="margin-top:13px">Klientská přihlašovací obrazovka chrání přístup v rozhraní. U statické stránky není server, který by mohl ověřit oprávnění proti úpravě v prohlížeči. GitHub token proto dávej jen lidem, kterým dovoluješ zapisovat do repozitáře.</div>`}
function validImportedData(k,v){if(['events','users','admins','staff'].includes(k))return Array.isArray(v);if(k==='roster')return v&&typeof v==='object'&&!Array.isArray(v);if(k==='playbook')return v&&typeof v==='object'&&Array.isArray(v.entries);return v&&typeof v==='object'&&!Array.isArray(v)}
function exportBackup(){const data={};for(const k of Object.keys(DATA_FILES))data[k]=state[k];const payload={app:'Freezers ESPORT Team Hub',version:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`freezers-esport-zaloha-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('JSON záloha byla stažena.')}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),payload=parsed.data||parsed,valid=Object.keys(DATA_FILES).filter(k=>Object.hasOwn(payload,k)&&validImportedData(k,payload[k]));if(!valid.length)throw Error('V souboru nebyla nalezena platná týmová data.');if(!confirm(`Načíst ${valid.length} datových souborů? Aktuální místní kopie se nahradí.`))return;valid.forEach(k=>state[k]=payload[k]);saveLocal();render();toast(`Načteno ${valid.length} souborů ze zálohy.`)}catch(err){toast(`Zálohu nelze načíst: ${err.message}`,'error')}};reader.readAsText(file)}
function isAdmin(){return state.userRole==='owner'||state.userRole==='admin'}
function hexBytes(hex){return Uint8Array.from(hex.match(/.{1,2}/g)||[],b=>parseInt(b,16))}
function toHex(bytes){return [...new Uint8Array(bytes)].map(v=>v.toString(16).padStart(2,'0')).join('')}
async function passwordDigest(password,salt,iterations=600000){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:hexBytes(salt),iterations,hash:'SHA-256'},material,256);return toHex(bits)}
async function login(form){
  const data=new FormData(form),username=String(data.get('username')||'').trim(),password=String(data.get('password')||''),token=String(data.get('token')||'').trim(),account=state.admins.find(a=>String(a.username).toLowerCase()===username.toLowerCase());
  if(!account){toast('Tento účet neexistuje. Požádej ownera o založení účtu.','error');return}
  try{const check=await passwordDigest(password,account.salt,account.iterations||600000);if(check!==account.passwordHash){toast('Nesprávné heslo.','error');return}}
  catch(err){toast('Přihlášení nelze ověřit. Otevři aplikaci přes HTTPS nebo localhost.','error');return}
  if(!token){toast('Zadej svůj GitHub token.','error');return}
  state.username=account.username;state.userRole=account.role||'member';state.currentUser=account.username;state.token=token;state.authenticated=false;state.github=false;
  toast('Ověřuji GitHub token a přístup k týmovým souborům…');
  try{await syncAll();state.authenticated=true;setCookie('freezers_user',state.username);render();toast('Přihlášení proběhlo. Vítej ve Freezers ESPORT.')}
  catch(err){state.github=false;state.token='';state.currentUser=null;state.userRole=null;toast('Přihlášení se nezdařilo: GitHub token nemá přístup k repozitáři. '+err.message,'error')}
}function logout(){state.authenticated=false;state.github=false;state.token='';state.currentUser=null;state.userRole=null;state.username='FILAS';document.getElementById('loginPassword').value='';document.getElementById('loginToken').value='';render();openLogin()}
async function createAccount(form){if(state.userRole!=='owner'){toast('Nové účty může vytvářet jen owner.','error');return}const data=new FormData(form),username=String(data.get('username')||'').trim(),password=String(data.get('password')||''),role=data.get('role')==='admin'?'admin':'member';if(state.admins.some(a=>a.username.toLowerCase()===username.toLowerCase())){toast('Toto uživatelské jméno už existuje.','error');return}if(password.length<10){toast('Heslo musí mít alespoň 10 znaků.','error');return}const salt=toHex(crypto.getRandomValues(new Uint8Array(16)));try{const passwordHash=await passwordDigest(password,salt);state.admins.push({username,role,salt,passwordHash,iterations:600000,createdAt:new Date().toISOString()});saveLocal();log(`${state.username} vytvořil účet ${username} (${role}).`,'♟');persist('admins');render();toast(`Účet ${username} byl vytvořen.`)}catch(err){toast(`Účet se nepodařilo vytvořit: ${err.message}`,'error')}}
async function changePassword(form){const data=new FormData(form),oldPassword=String(data.get('currentPassword')||''),newPassword=String(data.get('newPassword')||''),account=state.admins.find(a=>a.username.toLowerCase()===state.username.toLowerCase());if(!account||await passwordDigest(oldPassword,account.salt,account.iterations||600000)!==account.passwordHash){toast('Současné heslo není správné.','error');return}if(newPassword.length<10){toast('Nové heslo musí mít alespoň 10 znaků.','error');return}const salt=toHex(crypto.getRandomValues(new Uint8Array(16)));account.salt=salt;account.passwordHash=await passwordDigest(newPassword,salt);account.iterations=600000;saveLocal();log(`${state.username} změnil své heslo.`,'⚿');persist('admins');form.reset();toast('Heslo bylo změněno.')}
function openLogin(){if(state.authenticated){location.hash='member';return}$('#loginScreen').hidden=false;$('#loginUsername').focus()}
$('#loginClose').addEventListener('click',()=>$('#loginScreen').hidden=true);
function restrictedPrompt(area){return `${pageHeading('ČLENSKÁ SEKCE',area==='kalendář'?'Kalendář týmu':'Týmový playbook','Tato část je dostupná přihlášeným členům.',`<button class="btn btn-primary" data-action="open-login">Přihlásit se →</button>`)}<section class="panel"><div class="empty"><b>Nejdřív se přihlas do Freezers ESPORT</b>Vlož své týmové jméno, heslo a GitHub přístupový token.</div></section>`}
function renderMember(){if(!state.authenticated)return restrictedPrompt('členskou sekci');const ev=futureEvents().slice(0,5),mine=e=>Object.entries(state.rsvps[e.id]||{}).find(([u])=>u.toLowerCase()===state.username.toLowerCase())?.[1],yes=ev.filter(e=>mine(e)==='yes').length;return `${pageHeading('PLAYER HUB','Členská sekce',`Vítej zpět, ${esc(state.username)}. Tady máš týmový rozvrh a přístup k přípravě.`,`<button class="btn" data-action="logout">Odhlásit se</button>`)}<div class="stats-grid"><div class="stat-card"><div class="stat-label">PŘIHLÁŠENÝ ÚČET</div><div class="stat-value blue" style="font-size:25px">${esc(state.username)}</div><div class="stat-note">role ${esc(state.userRole||'member')}</div></div><div class="stat-card"><div class="stat-label">NADCHÁZEJÍCÍ AKCE</div><div class="stat-value">${ev.length}</div><div class="stat-note">v týmovém kalendáři</div></div><div class="stat-card"><div class="stat-label">POTVRZENÁ ÚČAST</div><div class="stat-value green">${yes}</div><div class="stat-note">zobrazených akcí</div></div><div class="stat-card"><div class="stat-label">ČLENSKÉ MATERIÁLY</div><div class="stat-value">${state.playbook.entries?.length||0}</div><div class="stat-note">taktik v playbooku</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h3>Kalendář týmu</h3><p>Potvrď účast nebo pošli omluvenku.</p></div><a class="text-link" href="#calendar">OTEVŘÍT →</a></div><div class="event-list">${ev.length?ev.slice(0,4).map(eventRow).join(''):'<div class="empty">Zatím nejsou naplánované akce.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>Členský playbook</h3><p>Callouty a týmové setupy.</p></div><a class="text-link" href="#playbook">OTEVŘÍT →</a></div><div class="empty"><b>${state.playbook.entries?.length||0} taktik připravených</b>Otevři playbook a prohlédni si setupy podle map.</div></section></div>`}
init();
